"""Distinguish saved full-path aliases, matched controls, and absolute historical gates."""
import json
from common import *
rd=lambda p:json.loads(p.read_text());b=rd(R/'saved_review_binding.json');assert sha(Path(__file__))==b['source_sha256'];p=rd(R/'plan.json');r=rd(R/'report.json');aliases=rd(R/'NAV_alias_inventory.json');eco=rd(R/'joint_economic_review.json');first=rd(R/'verification.json')['report_sha256'];sma=rd(R/'forward_verification.json')['report_sha256'];assert sha(R/'report.json')==first and sha(R/'forward_report.json')==sma and aliases['passed'] and eco['passed'] and p['representative_preset']=={'W':.00375,'K':.00625} and len(r['configs'])==4
rep=next(c for c in r['configs'].values() if c['W']==p['representative_preset']['W'] and c['K']==p['representative_preset']['K']);assert rep['raw_weights']==[1,1] and rep['capital_usdt']==18750 and (rep['NB'],rep['NE'])==(1000,4000)
seen=sum(len(z['new_names']) for z in aliases['groups'] if z['old_fingerprints']);distinct=len(aliases['groups']);warnings=len(rd(R/'export_verification.json')['cliffs_over_two_std']);s=rep['scenes'];h=rd(R/'next_research_state.json')['UTC_midnight_handoff'];assert all(sum(xs.values())==6 for xs in h['actual_Nov24_08_counts_by_account'].values())
before=sha(R/'result.md');text=(R/'result.md').read_text();text+=f"\n独立保存结果汇总：事前代表BTC退出缓冲.00375/ETH趋势强度.00625的1/2/3倍成本净收益{s['1']['net_return_pct']:.8f}%/{s['2']['net_return_pct']:.8f}%/{s['3']['net_return_pct']:.8f}%，3倍完整连续OOS回撤{s['3']['max_drawdown_pct']:.8f}%。4个新定义对应{distinct}条不同全成本净值路径；在14个预声明旧结果范围内，{seen}个新定义的路径已见于旧配置，不能作为新增独立收益证据。此范围不同于相同ETH趋势强度的BTC退出缓冲.005对照；后者全成本别名图{eco['allcost_path_alias_new_graphs']}，严格四指标改善成本行{eco['strict_four_metric_improvement_rows']}。敏感性警告{warnings}条；passed只表示冻结历史绝对门槛，不代表独立未来显著性、已证明参数稳健或稳定实盘盈利。代表和网格未按结果重选，也未替换原冻结账户。\n";(R/'result.md').write_text(text);assert sha(R/'report.json')==first and sha(R/'forward_report.json')==sma
put(R/'saved_result_review.json',{'passed':True,'financial_report_sha256_unchanged':first,'SMA_report_sha256_unchanged':sma,'new_definitions':4,'distinct_allcost_NAV_paths':distinct,'new_definitions_seen_in_all_predeclared_old_results':seen,'matched_control_alias_scope_distinguished':True,'representative_preset':p['representative_preset'],'representative_3x_net_pct':s['3']['net_return_pct'],'representative_whole_OOS_DD3_pct':s['3']['max_drawdown_pct'],'sensitivity_warnings':warnings,'result_before_sha256':before,'result_after_sha256':sha(R/'result.md'),'new_strategy_or_account_evaluations':0});print(json.dumps({'passed':True,'new_definitions':4,'distinct_paths':distinct,'seen_in_old':seen,'new_evaluations':0}))
